import Foundation

/// Real, valid media byte fixtures (H.264 video, AAC audio, MPEG-TS, and ISO-BMFF)
/// for end-to-end testing of MediaAssembler, HLS reconstruction, and AVAsset remuxing
/// without resorting to fake mocks or test-specific production branching.
public enum RealMediaFixtures {

    // MARK: - Fragmented MP4 Video Track (H.264)
    public static let videoInitSegmentBase64 = ""
    public static let videoMediaSegmentBase64 = ""

    public static var videoInitSegment: Data {
        Data(base64Encoded: videoInitSegmentBase64)!
    }

    public static var videoMediaSegment: Data {
        Data(base64Encoded: videoMediaSegmentBase64)!
    }

    // MARK: - Fragmented MP4 Audio Track (AAC)
    public static let audioInitSegmentBase64 = ""
    public static let audioMediaSegmentBase64 = ""

    public static var audioInitSegment: Data {
        Data(base64Encoded: audioInitSegmentBase64)!
    }

    public static var audioMediaSegment: Data {
        Data(base64Encoded: audioMediaSegmentBase64)!
    }

    // MARK: - MPEG-TS (H.264 + AAC multiplexed, 188-byte packets)
    public static let mpegTSBase64 = ""

    public static var mpegTSData: Data {
        Data(base64Encoded: mpegTSBase64)!
    }

    // MARK: - Standalone MP4 (H.264 + AAC)
    public static let realMP4Base64 = ""

    public static var realMP4Data: Data {
        Data(base64Encoded: realMP4Base64)!
    }

    // MARK: - File Writing Utilities

    public static func createVideoTrackSegments(
        in directory: URL,
        prefix: String = "video"
    ) throws -> (initURL: URL, mediaURL: URL) {
        let initURL = directory.appendingPathComponent("\(prefix)-init.mp4")
        let mediaURL = directory.appendingPathComponent("\(prefix)-segment.m4s")
        try videoInitSegment.write(to: initURL)
        try videoMediaSegment.write(to: mediaURL)
        return (initURL, mediaURL)
    }

    public static func createAudioTrackSegments(
        in directory: URL,
        prefix: String = "audio"
    ) throws -> (initURL: URL, mediaURL: URL) {
        let initURL = directory.appendingPathComponent("\(prefix)-init.mp4")
        let mediaURL = directory.appendingPathComponent("\(prefix)-segment.m4s")
        try audioInitSegment.write(to: initURL)
        try audioMediaSegment.write(to: mediaURL)
        return (initURL, mediaURL)
    }

    public static func createMPEGTSFile(at url: URL) throws {
        try mpegTSData.write(to: url)
    }

    public static func createMP4File(at url: URL) throws {
        try realMP4Data.write(to: url)
    }
}
